catalog_script_client.script:
function onLoad() {
    aplicarMascaraPercentual('v_percentual_da_rcl_investimento_empenhado');
    aplicarMascaraPercentual('v_percentual_da_rcl_investimento_liquidado');
    aplicarMascaraPercentual('v_percentual_da_rcl_investimento_pago');
}

function aplicarMascaraPercentual(variableName) {
    var field = g_form.getControl(variableName);
    if (!field) return;

    var rawValue = '';

    field.addEventListener('input', function () {
        rawValue = this.value.replace(/\D/g, '');

        if (rawValue === '') {
            this.value = '';
            return;
        }

        var number = parseFloat(rawValue) / 100;

        this.value = number.toLocaleString('pt-BR', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }) + '%';
    });
}
